style.css:
@-moz-document domain("iready.com") {
/* Set a light pink background for the body */
    .content-wrapper {
        background-color: #f9c1d2 !important; /* Light Pink */
        color: #333 !important; /* Dark text for contrast */
    }

    /* Change header background to hot pink */
    .main-header, .header, .top-bar {
        background-color: #ff69b4 !important; /* Hot pink */
    }

    /* Style the navigation bar with a deep pink */
    .navbar, .menu-bar {
        background-color: #ff1493 !important; /* Deep pink */
    }

    .navbar a, .menu-bar a {
        color: white !important;
        font-size: 1.2rem !important;
        padding: 10px 20px !important;
        text-decoration: none !important;
    }

    /* Hover effect for navigation links */
    .navbar a:hover, .menu-bar a:hover {
        background-color: #db1076 !important; /* Slightly darker pink */
        border-radius: 4px !important;
    }

    /* Style the buttons with a deep pink color */
    button, .button, .btn {
        background-color: #ff1493 !important;
        color: white !important;
        border: none !important;
        padding: 12px 24px !important;
        font-size: 1rem !important;
        border-radius: 4px !important;
        cursor: pointer !important;
        transition: background-color 0.3s ease !important;
    }

    /* Hover effect for buttons */
    button:hover, .button:hover, .btn:hover {
        background-color: #db1076 !important;
    }

    /* Style the footer with the same hot pink color */
    .footer, footer {
        background-color: #ff69b4 !important; /* Hot Pink */
        color: white !important;
        text-align: center !important;
        padding: 15px !important;
    }
}
